from flask import Flask, render_template_string
app = Flask(__name__)
PAGE = """<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>SnapClass · AI Attendance</title><style>body{margin:0;background:#07111f;color:#eef5ff;font-family:Inter,system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:72px 24px}.eyebrow{letter-spacing:.16em;text-transform:uppercase;color:#8ec5ff;font-size:12px}.hero{font-size:clamp(44px,7vw,82px);line-height:.98;margin:16px 0}.sub{max-width:700px;color:#b8c7d9;font-size:19px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin-top:40px}.card{border:1px solid #1f3249;border-radius:20px;padding:22px;background:#0b1828}.chip{display:inline-block;padding:8px 12px;border-radius:999px;background:#13263c;color:#9fd0ff}.cta{display:inline-block;margin-top:26px;padding:14px 18px;border-radius:12px;background:#eef5ff;color:#07111f;text-decoration:none;font-weight:700}</style></head><body><main><div class='eyebrow'>Ayush Kumar Gupta · SnapClass</div><h1 class='hero'>Attendance,<br>engineered for trust.</h1><p class='sub'>A modular attendance platform using face verification, voice verification, signed QR enrollment, role-based workflows and auditable records.</p><a class='cta' href='https://github.com/Blood79/SnapClass-AI-Attendance-System'>View source on GitHub →</a><section class='grid'><article class='card'><span class='chip'>01 · Vision</span><h2>Face verification</h2><p>Optional 128-D face descriptors behind a narrow adapter interface.</p></article><article class='card'><span class='chip'>02 · Voice</span><h2>Voice verification</h2><p>MFCC and delta fingerprints with configurable cosine thresholds.</p></article><article class='card'><span class='chip'>03 · QR</span><h2>Signed enrollment</h2><p>HMAC-signed, expiring tokens make QR enrollment payloads tamper-evident.</p></article><article class='card'><span class='chip'>04 · Data</span><h2>Audit-friendly records</h2><p>Attendance rules are separated from UI and persistence for testing and traceability.</p></article></section></main></body></html>"""
@app.get("/")
def index(): return render_template_string(PAGE)
if __name__ == "__main__": app.run(host="0.0.0.0", port=5000, debug=False)
